    "rootCauseDescription": "Foi verificado com a equipe técnica que a inspeção de recebimento da aeronave foi realizada, porém com o formulário antigo, que era \num check-list geral para todos os modelos de aeronaves especificados na E.O. da HBR Aviação. Entretanto, o setor de Qualidade da \nHBR Aviação montou um formulário de recebimento específico para aeronaves de modelo A109E, A109S e AW109SP. Este formulário \nFLL-001 REV.01 foi colocado junto ao dossiê da aeronave posteriormente ao seu recebimento na Oficina de Manutenção da base de \nBrusque, porém o responsável pelo Controle Técnico de Manutenção (CTM) não enfatizou ao inspetor quanto a essa atualização, que \npressupôs apenas que havia tido uma atualização simples no layout do antigo formulário. Dessa forma, tem-se que a causa raiz \nidentificada foi uma violação de rotina",
