    "rootCauseDescription": "Armazenamento inadequado de carenagens removidas das aeronaves:\n•\tCausa raiz: Ausência de planejamento e provisão de equipamentos específicos para o armazenamento seguro de carenagens durante as manutenções. Isso pode decorrer de uma análise insuficiente das necessidades operacionais ou de uma falha na alocação de recursos para a aquisição de prateleiras e suportes adequados.\nFalta de local adequado e climatizado para componentes removidos das aeronaves:\n•\tCausa raiz: Desconsideração dos requisitos ambientais necessários para a preservação de componentes sensíveis ao planejar as instalações da base. A ausência de uma área climatizada pode resultar de uma falha na avaliação dos padrões de armazenamento exigidos para manter a integridade desses componentes.\nIluminação deficiente no hangar de manutenção:\n•\tCausa raiz: Falta de manutenção preventiva e inspeções regulares do sistema de iluminação, levando à deterioração e insuficiência das condições de trabalho. Além disso, a ausência de um cronograma de manutenção pode resultar na não substituição de lâmpadas ou equipamentos de iluminação obsoletos ou danificados.",
