    "responsableSector": "Oficina de Manutenção de Célula",
    "rootCauseDescription": "Conforme registrado na Não Conformidade NC005, identificada durante a primeira auditoria interna na base de Brusque (I007_HBRSC_2023), foi solicitada a aquisição de novos armários. Após a entrega dos mesmos, foi realizada a segregação entre produtos aeronáuticos e produtos de limpeza. Dessa maneira, um armário foi destinado à Ferramentaria da base, onde foram armazenados todos os produtos aeronáuticos em condições de uso, enquanto os produtos de limpeza permaneceram no armário localizado na sala de lavagem, juntamente com os produtos aeronáuticos impróprios para uso. No entanto, como a equipe técnica da filial não utiliza o armário destinado aos produtos de limpeza, que é exclusivo para a equipe de limpeza da Fazenda Aero Amil, os itens mencionados na NC005 foram inadvertidamente esquecidos.",
