    "responsableSector": "Pricing",
    "rootCauseDescription": "Constatado procedimento inconsistente de orçamento de inspeções para Linha Bell.\nDurante verificação da O.S “CSP – 1529/2025”, da aeronave PT-YZL (Bell 407), foi constatado que não foi considerado a oferta das inspeções de “6 eventos” na venda do serviço de inspeção de 300 horas/12 meses – Task DMC-407-A-05-40-00-06A-281A-A pelo setor de Pricing. \nConforme a seção “SCHEDULED INSPECTIONS - DMC-407-A-05-00-00-00A-281A-A” do manual da Linha Bell, para o programa de “Airframe Periodic Inspection Program” é exigido que a cada 12 meses ou a cada 300 horas seja realizado as inspeções de “6 eventos” na aeronave.\nVerificado que o Gestor da Base teve que realizar contato com o setor de Pricing, Comercial e CTM para que os “6 eventos” fossem incluídos no orçamento e no escopo do serviço. Entretanto, não foi identificado referência as tarefas na Ordem de Serviço",
    "rootCauseCode": "PO3",
    "pacResponsibleName": "Gustavo Benatti",
