    "rootCauseDescription": "Ausência de um responsável para realizar a gestão das necessidades de SESMT 30/05/2023 - Causa Raiz: Não monitoramento do Inspetor de Manutenção ao observar que o mecânico não utilizava os equipamentos de segurança necessários para a atividade que estava realizando. E descumprimento do mecânico ao não utilizar os equipamentos de  segurança, desrespeitando os procedimentos descritos no MOM. Além da responsabilidade dos Inspetores, a responsável pelo SESMT contratada mantém o fluxo de conscientização e importância do uso dos EPIs para todos os colaboradores. Dentro do escopo de trabalho, realiza caminhadas diárias e notifica os funcionários que não estão adequados com o uso dos equipamentos de proteção. Também possuimos em nosso Manual de Conduta, as penalidades para casos de violação do não uso do EPI.",
