    "responsableSector": "Auditoria",
    "rootCauseDescription": "Falta de aderência para a sistemática de verificação das ações corretivas em médio-longo prazo.\nApesar de ser verificado a implementação e efetividade das ações corretivas após o encerramento de uma não conformidade ou finalização das ações propostas pelo auditado, a verificação da eficácia era realizada em um curto prazo, sem haver um acompanhamento e monitoramento a médio-longo prazo para avaliar a real aderência das ações propostas.                                                                   Verificação de Abrangência NC: Foi realizado uma nova verificação de eficácia de todos os planos de ação corretiva referente as não conformidades pontuadas nas duas últimas auditorias da CMAvex no HBR, buscando detectar ações que não foram efetivas após implementações.",
